def calcular_frete(peso_kg: float, regiao: str, valor_pedido: float,
                   cupom: str | None = None, expresso: bool = False) -> float:
    # ---------- 1. Validação ----------
    if not (peso_kg > 0 and peso_kg <= 30):
        raise ValueError("Peso inválido")
    if regiao not in ("S", "SE", "CO", "NE", "N"):
        raise ValueError("Região inválida")
    if valor_pedido < 0:
        raise ValueError("Valor do pedido inválido")

    # ---------- 2. Tarifa base por peso ----------
    if peso_kg <= 1.0:
        base = 12.00
    elif peso_kg <= 5.0:
        extra_kg = math.ceil(peso_kg - 1)          # fração acima de 1 kg
        base = 12.00 + 3.50 * extra_kg
    else:                                           # > 5 kg
        extra_kg = math.ceil(peso_kg - 5)          # fração acima de 5 kg
        base = 26.00 + 2.80 * extra_kg

    # ---------- 3. Multiplicador regional ----------
    multiplicadores = {"S": 1.0, "SE": 1.0, "CO": 1.2,
                      "NE": 1.35, "N": 1.5}
    tarifa_regional = base * multiplicadores[regiao]

    # ---------- 4. Expresso ----------
    if expresso:
        tarifa = tarifa_regional * 1.40
    else:
        tarifa = tarifa_regional

    # ---------- 5. Frete grátis ----------
    if (valor_pedido >= 299.90 and not expresso and
            regiao in ("S", "SE", "CO")):
        return 0.0  # cupom ignorado

